import type {
  ImpactSummary,
  SelectableActionItem,
  SmogActionPlan,
} from "@/types";

const MAX_EXPOSURE_REDUCTION_PCT = 90;
const SINGLE_ITEM_MAX_PCT = 45;
const AVG_CAR_CO2E_KG_PER_KM = 0.192;

/**
 * Normalizes a SmogActionPlan into a flat list of selectable items for the
 * interactive "What-If" Impact Calculator.
 *
 * @param plan - Personalized action plan generated by Gemini or fallback mode.
 * @returns Ordered list of selectable items across routine, indoor hacks, and alternatives.
 */
export function extractSelectableItems(
  plan: SmogActionPlan,
): SelectableActionItem[] {
  const routineItems: SelectableActionItem[] = plan.routine.map((item) => ({
    id: item.id,
    group: "routine",
    title: `${item.period.toUpperCase()}: ${item.title}`,
    impact: item.impact,
  }));

  const hackItems: SelectableActionItem[] = plan.indoorHacks.map((item) => ({
    id: item.id,
    group: "indoor-hack",
    title: item.title,
    impact: item.impact,
  }));

  const alternativeItems: SelectableActionItem[] =
    plan.sustainableAlternatives.map((item) => ({
      id: item.id,
      group: "sustainable-alternative",
      title: item.recommendedSwap,
      impact: item.impact,
    }));

  return [...routineItems, ...hackItems, ...alternativeItems];
}

/**
 * Calculates realistic cumulative health exposure reduction and weekly community
 * emission savings from the checked actions.
 *
 * Exposure reduction uses multiplicative compounding on remaining exposure:
 *   R_total = 1 - Π(1 - r_i)
 * capped at 90% so layered protections never claim an unrealistic >100% reduction.
 *
 * @param items - All selectable action items in the current plan.
 * @param selectedIds - Set of item IDs currently checked by the user.
 * @returns Aggregated health and environmental impact metrics.
 */
export function calculateImpactSummary(
  items: readonly SelectableActionItem[],
  selectedIds: ReadonlySet<string>,
): ImpactSummary {
  let remainingExposureFactor = 1;
  let weeklyCo2eSavedKg = 0;
  let weeklyPmGramsSaved = 0;
  let selectedCount = 0;

  for (const item of items) {
    if (!selectedIds.has(item.id)) {
      continue;
    }
    selectedCount += 1;
    const clampedPct = Math.min(
      SINGLE_ITEM_MAX_PCT,
      Math.max(0, item.impact.exposureReductionPct),
    );
    remainingExposureFactor *= 1 - clampedPct / 100;
    weeklyCo2eSavedKg += Math.max(0, item.impact.weeklyCo2eSavedKg);
    weeklyPmGramsSaved += Math.max(0, item.impact.weeklyPmGramsSaved);
  }

  const rawReduction = (1 - remainingExposureFactor) * 100;
  const cumulativeExposureReductionPct = Math.min(
    MAX_EXPOSURE_REDUCTION_PCT,
    Math.round(rawReduction),
  );
  const roundedCo2e = Math.round(weeklyCo2eSavedKg * 10) / 10;
  const roundedPm = Math.round(weeklyPmGramsSaved * 10) / 10;
  const equivalentCarKmAvoided =
    Math.round((roundedCo2e / AVG_CAR_CO2E_KG_PER_KM) * 10) / 10;

  const { tierLabel, tierDescription } = classifyImpactTier(
    selectedCount,
    cumulativeExposureReductionPct,
  );

  return {
    selectedCount,
    totalCount: items.length,
    cumulativeExposureReductionPct,
    weeklyCo2eSavedKg: roundedCo2e,
    weeklyPmGramsSaved: roundedPm,
    equivalentCarKmAvoided,
    tierLabel,
    tierDescription,
  };
}

function classifyImpactTier(
  selectedCount: number,
  reductionPct: number,
): { tierLabel: string; tierDescription: string } {
  if (selectedCount === 0) {
    return {
      tierLabel: "Baseline Exposure",
      tierDescription:
        "Select any routine adjustment, indoor hack, or sustainable swap to model your impact.",
    };
  }
  if (reductionPct < 25) {
    return {
      tierLabel: "Starter Shield",
      tierDescription:
        "Meaningful first steps—layering filtration with peak-hour avoidance compounds protection.",
    };
  }
  if (reductionPct < 50) {
    return {
      tierLabel: "Resilient Household",
      tierDescription:
        "Strong multi-layered protection lowering both indoor PM2.5 inhalation and local emissions.",
    };
  }
  if (reductionPct < 70) {
    return {
      tierLabel: "Winter Smog Defender",
      tierDescription:
        "High-impact routine and clean-air swaps substantially shielding vulnerable family members.",
    };
  }
  return {
    tierLabel: "Clean-Air Champion",
    tierDescription:
      "Maximum realistic winter smog defense paired with measurable weekly community emission cuts.",
  };
}
